"""Explain swait signal cleanup, finish, common exits and wrapper states."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1501': ('준비물을 기다리던 친구가 중단 연락을 받고 떠난다면 대기 카드도 빼야 합니다. 카드를 그대로 두면 다음에 한 사람만 부를 때 떠난 친구의 카드를 고를 수 있기 때문입니다.', '신호 중단에서 대기 항목을 제거하는 이유와 조건 확인 순서를 이해합니다.', '준비 함수의 결과와 조건을 두 칸으로 나누세요. 결과가 중단 코드여도 조건이 참이면 공통 반복문에서 어느 길로 가는지 화살표를 그리세요.', ['prepare_to_swait_event는 기다릴 준비를 하는 함수입니다. 먼저 줄의 raw 잠금을 잡고 해당 CPU의 인터럽트 상태를 저장합니다. 등록과 제거를 다른 작업의 줄 변경과 겹치지 않게 보호하는 구간입니다.', 'signal_pending_state는 지금 대기 상태에서 중단을 허용하는 신호가 와 있는지 확인합니다. 신호는 작업에게 보내는 알림입니다. 알림이 하나라도 있으면 모든 종류의 대기가 중단되는 것은 아닙니다. state라는 대기 규칙도 함께 봅니다.', '허용된 신호가 있으면 list_del_init으로 항목을 줄에서 빼고 연결을 자기 자신으로 초기화합니다. 그리고 -ERESTARTSYS라는 음수 중단 코드를 준비합니다. 이 함수의 약속은 -EINTR가 아닙니다. 다른 함수에서 본 오류 이름을 그대로 대입하면 안 됩니다.', '왜 떠날 항목을 먼저 뺄까요? 다음 swake_up_one은 맨 앞 한 항목을 처리하기 때문입니다. 중단할 항목이 남아 있으면 다른 대기자 대신 그 항목이 선택될 수 있습니다. 제거는 메모리를 없애는 일이 아니라 줄 연결을 정리하는 일입니다.', '신호가 없으면 __prepare_to_swait로 현재 작업을 등록하고 set_current_state로 대기 상태를 정합니다. 신호가 있는 분기에는 이 상태 설정 명령이 없습니다. 두 분기 모두 끝에는 잠금을 풀고 저장했던 인터럽트 상태를 복구한 뒤 결과를 돌려줍니다.', '공통 ___swait_event는 준비 함수가 돌아오면 먼저 조건을 봅니다. 이미 조건이 참이면 성공 쪽으로 반복을 끝내고 정리합니다. 조건이 거짓일 때 중단 가능한 상태와 준비 오류를 확인해 중단 코드를 돌려줍니다. 그러므로 준비 함수의 오류만 보고 공통 매크로의 최종 결과까지 단정하지 마세요.'], [('준비 함수가 허용된 신호를 발견했어요. 어떤 중단 코드를 준비하나요?', ['언제나 -EINTR예요', '-ERESTARTSYS예요'], '원문은 ret = -ERESTARTSYS라고 적습니다. 오류 코드는 함수별 약속이라 다른 대기 함수의 -EINTR와 바꾸어 읽으면 안 돼요. 공통 매크로의 최종 결과는 이어지는 조건 검사까지 따라가야 합니다.'), ('중단할 항목을 다음 swake_up_one이 다시 고르도록 줄에 남겨 두나요?', ['아니요. 신호 분기에서 줄에서 빼요', '네. 다른 대기자보다 먼저 선택되게 해요'], 'list_del_init으로 제거하므로 다음 한 항목 깨우기의 대상에 남지 않습니다. 떠날 친구의 카드를 빼야 아직 기다리는 친구에게 호출 기회가 갈 수 있다는 예시로 생각해 보세요.')]), 'os1502': ('기다림이 끝났다면 내 상태를 “활동 가능”으로 바꾸고 대기 카드도 정리해야 합니다. 이미 담당자가 카드를 빼 주었다면 다시 찾을 필요가 없지만, 남아 있다면 명단을 보호하면서 빼야 합니다.', '기다림 종료에서 작업 상태 복원과 안전한 목록 제거를 구별합니다.', 'finish_swait의 순서를 상태 복원 → 연결 확인 → 남아 있으면 잠금 잡기 → 제거·초기화 → 잠금 풀기로 그리세요.', ['finish_swait는 기다림을 마무리합니다. 첫 명령 __set_current_state(TASK_RUNNING)은 현재 작업을 실행 가능한 상태로 되돌립니다. 이름이 RUNNING이라고 그 순간 여러 CPU 중 특정 CPU에서 계속 실행할 권리를 얻는다는 뜻은 아닙니다.', '다음 list_empty_careful은 항목의 앞뒤 연결을 조심스럽게 확인합니다. 두 연결이 자기 자신을 가리키는 빈 상태인지 살피는 검사입니다. 깨우는 쪽이 이미 항목을 제거했을 수 있어서 먼저 확인합니다.', 'careful은 영어로 조심스럽다는 뜻이지만 모든 동시 변경에 안전한 마법은 아닙니다. 이 사용은 항목 제거와 종료에 맞는 정해진 규칙 안에서 이루어집니다. 다른 코드가 마음대로 같은 항목을 새 줄에 다시 추가해도 안전하다고 넓혀 해석하면 안 됩니다.', '항목이 남아 있으면 raw_spin_lock_irqsave로 잠금을 잡고 인터럽트 상태를 저장합니다. 그 안에서 list_del_init으로 줄에서 빼고 연결을 초기화합니다. 이후 잠금을 풀며 인터럽트 상태를 복구합니다. 처음 확인은 밖에서 하지만 실제 제거는 잠금 안에서 합니다.', '__finish_swait라는 내부 함수는 다릅니다. 상태를 복원하고 일반 list_empty 검사와 list_del_init을 하지만 직접 잠금을 잡지 않습니다. 호출하는 쪽에서 필요한 보호를 갖춘 경우에 사용하는 함수입니다. 밑줄이 더 많다고 보호도 더 많은 것은 아닙니다.', '대기 항목을 함수의 지역 공간인 스택에 만들었다면 그 공간을 더는 쓸 수 없게 되기 전에 줄에서 빠져야 합니다. 그렇지 않으면 나중에 깨우는 코드가 오래된 주소를 따라가 잘못된 자료를 만질 수 있습니다. 상태 복원, 줄 제거, 자료의 사용 기간을 함께 확인하는 이유입니다.'], [('finish_swait에서 항목이 남아 있어 실제로 제거할 때에는 잠금을 잡나요?', ['아니요. 확인부터 제거까지 모두 잠금 없이 해요', '네. 실제 제거는 raw 잠금 안에서 해요'], 'careful 조회는 잠금 밖에 있지만 list_del_init은 irqsave로 잡은 잠금 안에 있습니다. 읽어 보는 단계와 줄 연결을 바꾸는 단계를 구별하세요.'), ('내부 __finish_swait도 스스로 잠금을 잡아 주나요?', ['아니요. 호출자가 필요한 보호를 마련해야 해요', '네. 이름에 밑줄이 있으면 언제나 잠금까지 포함해요'], '내부 함수에는 상태 변경, 빈 연결 검사, 제거 명령이 있고 잠금 명령은 없습니다. 이름이 비슷해도 외부 finish_swait와 사용 조건이 같지 않습니다.')]), 'os1503': ('길 안내에 “성공하면 정리대를 지나 출구로, 중단하면 지정 출구로 바로 가세요”라는 두 화살표가 있다고 해 봅시다. 어느 길에서도 같은 정리대를 지난다고 생각하면 실제 동작을 잘못 읽게 됩니다.', '공통 대기 반복문의 조건 성공과 신호 오류 경로를 따로 따라갑니다.', '준비 → 조건 참?를 그리고 참은 finish로, 거짓은 신호 오류 검사로 이으세요. 오류 화살표는 finish 뒤의 __out으로 직접 연결하세요.', ['___swait_event는 여러 swait 함수가 함께 쓰는 매크로입니다. 매크로는 코드를 번역하기 전에 정해 둔 코드로 펼치는 규칙입니다. 여기의 ({ ... })는 여러 명령을 실행하고 마지막 값을 결과로 쓰는 GNU C 확장 문법입니다.', '안에는 지역 대기 항목 __wait와 결과를 담을 long __ret가 있습니다. long은 정수 자료형이고, __ret는 전달받은 초기 결과 ret에서 시작합니다. INIT_LIST_HEAD로 항목 연결을 먼저 초기화해야 등록 여부를 검사할 수 있습니다.', 'for (;;)는 나갈 때까지 반복하라는 뜻입니다. 반복마다 prepare_to_swait_event로 준비하고 그 결과를 __int에 둡니다. 그다음 condition, 즉 기다리던 조건부터 확인합니다. 참이면 break로 반복문을 나와 finish_swait를 거칩니다.', '조건이 거짓이면 이 상태가 신호 중단을 검사하는 상태인지, 준비 결과 __int에 오류가 있는지 봅니다. 둘 다 맞으면 __ret에 오류를 넣고 goto __out으로 이동합니다. goto는 이름표가 붙은 위치로 실행을 옮기는 명령입니다.', '__out:은 finish_swait 바로 뒤에 있습니다. 그래서 이 신호 오류 길은 finish_swait 호출을 건너뜁니다. 준비 함수가 신호 분기에서 이미 항목을 제거했다는 규칙과 연결해서 읽어야 합니다. 소스에 없는 finish 호출이나 상태 변경을 상상해서 추가하면 안 됩니다.', '조건도 거짓이고 나갈 오류도 없으면 cmd를 실행합니다. wrapper가 schedule을 넣었다면 여기서 실행 기회를 넘기고 돌아와 다시 준비합니다. 조건은 여러 번 읽힐 수 있으므로 검사할 때마다 물건을 없애는 식으로 함부로 만들지 않습니다. swait에는 비 exclusive 선택 인자가 없으며, exclusive는 혼자만 등록 가능하다는 뜻이 아니라 깨우기 방식의 제한입니다.'], [('조건이 거짓이고 허용된 신호 오류로 goto __out을 실행했어요. finish_swait도 지나가나요?', ['네. 모든 출구는 반드시 finish_swait를 지나가요', '아니요. 그 호출 뒤의 __out으로 바로 이동해요'], '이름표 __out은 finish_swait 뒤에 있습니다. goto가 그곳으로 건너뛰므로 호출하지 않아요. 신호 준비 분기에서 이미 목록을 제거한 점까지 함께 봐야 정리 흐름을 이해할 수 있습니다.'), ('이 공통 swait 매크로에 비 exclusive 모드를 고르는 인자가 있나요?', ['아니요. swait는 모두 exclusive인 방식이에요', '네. 고르면 일반 사용자 콜백도 자동 등록해요'], '매크로 인자는 wq, condition, state, ret, cmd입니다. 일반 waitqueue처럼 exclusive 여부를 고르는 인자가 없고 임의 깨움 콜백 기능도 제공하지 않습니다. 대신 한 대기 줄에는 여러 항목이 들어갈 수 있습니다.')]), 'os1504': ('같은 기다림이라도 “중단 연락이 오면 나가기”와 “조건이 될 때까지 기다리기”는 규칙이 다릅니다. 입구에서 어떤 규칙을 골랐는지 알아야 결과를 바르게 읽을 수 있습니다.', '일반·신호 중단 가능·idle 대기의 상태와 반환 방식을 구별합니다.', '일반=TASK_UNINTERRUPTIBLE, interruptible=TASK_INTERRUPTIBLE, idle=TASK_IDLE의 세 줄 표를 만드세요. 이미 조건이 참인 경우에는 세 줄 모두 내부 대기 생략이라고 적으세요.', ['wrapper는 공통 코드에 정해진 인자를 넣어 사용하기 쉽게 감싼 입구입니다. swait의 각 입구는 대기 상태와 대기 명령, 결과 사용 방식을 정합니다. 이름이 비슷해도 같은 규칙을 고르는 것은 아닙니다.', 'swait_event_exclusive는 TASK_UNINTERRUPTIBLE 상태와 schedule을 선택합니다. 일반적인 신호 중단을 허용하는 TASK_INTERRUPTIBLE과 다릅니다. do { ... } while (0) 모양으로 문장처럼 쓰며, 성공 숫자를 변수에 받아 쓰는 함수처럼 다루지 않습니다.', 'swait_event_interruptible_exclusive는 TASK_INTERRUPTIBLE 상태를 사용합니다. 조건을 만족해 끝나면 0, 허용된 신호로 중단되면 -ERESTARTSYS를 결과로 줍니다. 여기서 0은 성공 표시입니다. 이 수업의 시간 제한 없는 변형을 timeout의 남은 시간 규칙과 섞지 마세요.', 'swait_event_idle_exclusive는 TASK_IDLE을 선택합니다. 이 기다림이 system load라는 부하 지표를 늘리지 않도록 하는 상태입니다. load는 CPU 사용률과 완전히 같은 숫자가 아닙니다. 원문은 이 대기에서 신호를 무시한다고 설명합니다.', 'idle이라고 CPU가 계속 바쁘게 조건을 검사하거나 컴퓨터 전체를 멈추는 것은 아닙니다. 실제 대기 명령은 schedule입니다. 실행 기회를 넘겼다가 다시 실행되면 조건을 확인합니다. 그래서 깨우는 쪽은 조건 변경과 알림의 규칙을 지켜야 합니다.', '각 바깥 wrapper는 조건부터 확인합니다. 이미 참이면 내부 등록과 실제 기다림을 건너뜁니다. 함수를 사용했다고 항상 잠든 것은 아닙니다. 어떤 상태를 쓸지 고를 때에는 swait가 같은 줄에서 서로 다른 수면 종류를 섞는 사용을 제한한다는 점도 지켜야 합니다.'], [('부하 집계에 이 기다림을 더하지 않는 idle wrapper는 어떤 상태를 고르나요?', ['언제나 TASK_INTERRUPTIBLE이에요', 'TASK_IDLE이에요'], '내부 호출에 TASK_IDLE이 적혀 있습니다. 신호로 중단할 수 있는 interruptible 변형과 다른 선택이에요. idle은 바쁜 반복 검사나 컴퓨터 전체의 정지를 뜻하지 않습니다.'), ('wrapper에 들어오자마자 기다리던 조건이 참이에요. 내부 대기 등록을 생략할 수 있나요?', ['네. 바깥 조건 검사에서 끝날 수 있어요', '아니요. 결과와 관계없이 반드시 한 번 잠들어요'], '바깥에서 조건을 확인하고 필요한 때에만 내부 대기를 부릅니다. 이미 준비물이 있다면 새로 대기 줄에 서지 않아도 되는 것과 같아요. 호출했다는 사실과 실제로 잠들었다는 사실을 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_371.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
